Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "title": {
    "text": "Average Gravity by PPG",
    "fontSize": 75,
    "font": "consolas",
    "subtitle": "2024-25 NBA Season | All data available players",
    "subtitleFontSize": 25,
    "subtitleFont": "consolas",
    "subtitleFontWeight": "bold",
    "subtitleColor": "darkslategray"
  },
  "encoding": {
    "y": {
      "field": "AVGGRAVITYSCORE",
      "type": "quantitative",
      "title": "Average Gravity Score",
      "axis": {
        "titleFont": "consolas",
        "labelFont": "consolas",
        "labelFontSize": 20,
        "titleFontSize": 40,
        "titlePadding": 12,
        "labelPadding": 6
      }
    },
    "x": {
      "field": "PTS",
      "type": "quantitative",
      "title": "Points Per Game",
      "axis": {
        "titleFont": "consolas",
        "labelFont": "consolas",
        "labelFontSize": 20,
        "titleFontSize": 40,
        "titlePadding": 12,
        "labelPadding": 6
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#6B7280",
        "strokeWidth": 2,
        "strokeDash": [
          8,
          6
        ],
        "opacity": 0.8
      },
      "encoding": {
        "x": {
          "aggregate": "mean",
          "field": "PTS",
          "type": "quantitative"
        },
        "y": null,
        "tooltip": [
          {
            "aggregate": "mean",
            "field": "PTS",
            "type": "quantitative",
            "title": "Mean Points Per Game",
            "format": ".2f"
          }
        ]
      },
      "encoding": {
        "x": {
          "aggregate": "mean",
          "field": "PTS",
          "type": "quantitative"
        },
        "y": null,
        "tooltip": [
          {
            "aggregate": "mean",
            "field": "PTS",
            "type": "quantitative",
            "title": "Mean Points Per Game",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#6B7280",
        "strokeWidth": 2,
        "strokeDash": [
          8,
          6
        ],
        "opacity": 0.8
      },
      "encoding": {
        "y": {
          "aggregate": "mean",
          "field": "AVGGRAVITYSCORE",
          "type": "quantitative"
        },
        "x": null,
        "tooltip": [
          {
            "aggregate": "mean",
            "field": "AVGGRAVITYSCORE",
            "type": "quantitative",
            "title": "Mean Gravity Score",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "image",
        "width": 55,
        "height": 40,
        "aspect": true,
        "align": "center",
        "baseline": "middle"
      },
      "encoding": {
        "url": {
          "field": "HEADSHOT_DATA_URI",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "name",
            "type": "nominal",
            "title": "Player"
          },
          {
            "field": "PTS",
            "type": "quantitative",
            "title": "Points Per Game"
          },
          {
            "field": "AVGGRAVITYSCORE",
            "type": "quantitative",
            "title": "Average Gravity"
          }
        ]
      }
    }
  ]
}'
